//! Designated host for the generated `Class3Multi` simulation CLI — HAND-WRITTEN.
//!
//! The CLI body is generated by the `language!` macro into
//! `target/generated/class3multi/simulate.rs` (`options { emit_simulator: true }`, the
//! default) and materialized here by the `class3multi_simulation_main!` wrapper. This file is
//! the cargo `[[bin]]` target; its stanza lives in `languages/Cargo.toml`.
//!
//! `Class3Multi` is TEST-hosted: its definition is not a library module, so this binary
//! `#[path]`-includes the definition file directly and passes `crate::class3multi` to the
//! wrapper. Compiling that `mod` is also what RUNS the `language!` macro for this crate,
//! which is what writes the body the wrapper includes — the wrapper is emitted by that
//! same expansion, so the write always precedes the include.

#[path = "../../tests/definitions/class3multi.rs"]
mod class3multi;

class3multi::class3multi_simulation_main!(crate::class3multi);
